package com.braseiro.dnd5e;
import org.json.JSONArray;import org.json.JSONObject;
/** Netheril's Fall (NF) bestiary runtime. Source-bound, deterministic, no source prose. */
public final class NetherilsFallBestiaryRuntimeEngine{
 public static final String SOURCE_CODE="NF",BOOK="Netheril's Fall",SOURCE_BLOB="bestiary-nf.json@main-2026-10-05";
 private static final String[] IDS={"Caldron Magen","Eldritch Eddy","Phaerimm Elder","Phaerimm Scout","Terran Magen","Virvos Magen"};
 private static JSONObject b(String n,int ac,int hp,String f,String type,double cr,int str,int dex,int con,int intel,int wis,int cha,int walk,int fly,boolean hover){try{
  JSONObject movement=new JSONObject().put("walk_ft",walk);if(fly>0)movement.put("fly_ft",fly).put("hover",hover);
  JSONObject abilities=new JSONObject().put("str",str).put("dex",dex).put("con",con).put("int",intel).put("wis",wis).put("cha",cha);
  JSONObject basis=new JSONObject().put("source_type","compiled_statblock").put("content_kind","statblock").put("content_name",n).put("source_book",BOOK).put("source_locator","5e.tools data/bestiary/bestiary-nf.json blob "+SOURCE_BLOB);
  return new JSONObject().put("id",n).put("name",n).put("source",SOURCE_CODE).put("source_book",BOOK)
   .put("armor_class",ac).put("hit_points",hp).put("hp_formula",f).put("creature_type",type).put("challenge_rating",cr)
   .put("movement",movement).put("abilities",abilities).put("senses",new JSONObject())
   .put("actions",new JSONArray()).put("traits",new JSONArray()).put("special_actions",new JSONArray())
   .put("mechanical_basis",basis).put("auto_rolls",false).put("full_statblock_claim",false)
   // Legacy aliases retained for older consumers; compiled authority uses the canonical keys above.
   .put("ac",ac).put("hp",hp).put("type",type).put("cr",cr);
 }catch(Exception e){return new JSONObject();}}
 private static JSONObject a(String n,String dmg,String type,int hit,int range){try{return new JSONObject().put("name",n).put("damage",dmg).put("damage_type",type).put("to_hit",hit).put("range_ft",range).put("manual_damage_roll",true);}catch(Exception e){return new JSONObject();}}
 private static JSONObject caldron(){JSONObject o=b("Caldron Magen",20,67,"9d8 + 27","construct",4,18,13,16,10,10,10,30,0,false);try{o.optJSONObject("senses").put("passive_perception",14);o.put("speed_walk_ft",30).put("immunities","acid, poison");o.optJSONArray("traits").put(new JSONObject().put("name","Magic Resistance").put("advantage_vs_spells_magical_effects",true)).put(new JSONObject().put("name","Disintegration").put("on_death","body disintegrates; carried/worn objects remain"));o.optJSONArray("actions").put(a("Extended Fist","1d8+4 + 1d10","bludgeoning + acid",6,15).put("grapple_medium_or_smaller",true).put("escape_dc",14)).put(a("Acid Spittle","2d8+4","acid",6,60));o.put("multiattack",new JSONObject().put("count",2).put("options","Extended Fist|Acid Spittle").put("manual_sequence_required",true));}catch(Exception ignored){}return o;}
 private static JSONObject eddy(){JSONObject o=b("Eldritch Eddy",11,144,"17d10 + 51","construct",6,10,12,16,12,9,17,10,40,true);try{o.optJSONObject("senses").put("blindsight_ft",60).put("passive_perception",9);o.put("speed_walk_ft",10).put("speed_fly_ft",40).put("hover",true).put("resistances","force").put("immunities","fire, lightning");o.optJSONArray("traits").put(new JSONObject().put("name","Magic Resistance").put("advantage_vs_spells_magical_effects",true));o.optJSONArray("actions").put(a("Searing Swipe","3d6+3","fire or lightning (explicit choice)",6,10)).put(a("Arcane Bolt","2d10+3","force",6,120));o.put("multiattack",new JSONObject().put("count",2).put("options","Searing Swipe|Arcane Bolt").put("manual_sequence_required",true));o.optJSONArray("special_actions").put(new JSONObject().put("name","Eldritch Overload").put("type","reaction").put("trigger","takes damage").put("save","STR DC 14").put("damage","2d6 force").put("condition_on_fail","Prone").put("radius_ft",5).put("manual_save_required",true));}catch(Exception ignored){}return o;}
 private static JSONObject elder(){JSONObject o=b("Phaerimm Elder",17,218,"23d12 + 69","aberration",14,18,16,17,17,16,18,30,60,true);try{o.optJSONObject("senses").put("truesight_ft",120).put("passive_perception",18);o.put("speed_walk_ft",30).put("speed_fly_ft",60).put("hover",true).put("truesight_ft",120).put("spell_save_dc",17);o.optJSONArray("traits").put(new JSONObject().put("name","Magic Resistance").put("advantage_vs_spells_magical_effects",true));o.optJSONArray("actions").put(a("Mind Lash","6d8+4","psychic",9,120).put("reach_ft",10)).put(a("Vicious Stinger","2d6+4 + 4d12","piercing + poison",9,5).put("speed_zero_until_next_turn",true)).put(new JSONObject().put("name","Siphon Magic").put("recharge","5-6").put("range_ft",10).put("drain_item_charges",true).put("manual_target_required",true));o.put("multiattack",new JSONObject().put("count",3).put("primary","Mind Lash").put("replace_one_with","Vicious Stinger|Command level 3").put("manual_sequence_required",true));o.optJSONArray("special_actions").put(new JSONObject().put("name","Teleport").put("type","bonus").put("distance_ft",30)).put(new JSONObject().put("name","Protective Magic").put("type","reaction").put("uses_per_day",3).put("options","Counterspell|Shield"));}catch(Exception ignored){}return o;}
 private static JSONObject scout(){JSONObject o=b("Phaerimm Scout",13,44,"8d8 + 8","aberration",2,12,13,12,15,16,16,10,40,false);try{o.optJSONObject("senses").put("truesight_ft",60).put("passive_perception",15);o.put("speed_walk_ft",10).put("speed_fly_ft",40).put("truesight_ft",60).put("spell_save_dc",13);o.optJSONArray("traits").put(new JSONObject().put("name","Magic Resistance").put("advantage_vs_spells_magical_effects",true));o.optJSONArray("actions").put(a("Stinger","1d6+1 + 2d8","piercing + poison",3,5)).put(a("Mindwarp Ray","1d6+3","psychic",5,120).put("condition_on_hit","Charmed until start of phaerimm next turn"));o.put("multiattack",new JSONObject().put("count",2).put("options","Stinger|Mindwarp Ray").put("manual_sequence_required",true));o.optJSONArray("special_actions").put(new JSONObject().put("name","Uncanny Dodge").put("type","reaction").put("trigger","hit by attack roll").put("effect","halve damage round down"));}catch(Exception ignored){}return o;}
 private static JSONObject terran(){JSONObject o=b("Terran Magen",21,121,"22d8 + 22","construct",8,16,10,12,10,18,10,30,20,true);try{o.optJSONObject("senses").put("passive_perception",17);o.put("speed_walk_ft",30).put("speed_fly_ft",20).put("hover",true).put("immunities","poison, thunder").put("spell_save_dc",15);o.optJSONArray("traits").put(new JSONObject().put("name","Magic Resistance").put("advantage_vs_spells_magical_effects",true)).put(new JSONObject().put("name","Disintegration").put("on_death","body disintegrates; carried/worn objects remain"));o.optJSONArray("actions").put(a("Hammer Fist","3d8+3 + 3d8","bludgeoning + force",6,5)).put(a("Thunderous Boom","8d6","thunder",7,60));o.put("multiattack",new JSONObject().put("count",2).put("options","Hammer Fist|Thunderous Boom").put("manual_sequence_required",true));}catch(Exception ignored){}return o;}
 private static JSONObject virvos(){JSONObject o=b("Virvos Magen",21,110,"17d8 + 34","construct",6,12,10,14,10,10,16,30,20,true);try{o.optJSONObject("senses").put("passive_perception",16);o.put("speed_walk_ft",30).put("speed_fly_ft",20).put("hover",true).put("immunities","poison, psychic").put("spell_save_dc",14);o.optJSONArray("traits").put(new JSONObject().put("name","Magic Resistance").put("advantage_vs_spells_magical_effects",true)).put(new JSONObject().put("name","Disintegration").put("on_death","body disintegrates; carried/worn objects remain"));o.optJSONArray("actions").put(a("Psychic Blast","6d6","psychic",6,60).put("reach_ft",5));o.put("multiattack",new JSONObject().put("count",2).put("action","Psychic Blast").put("manual_sequence_required",true));}catch(Exception ignored){}return o;}
 private static JSONObject[] records(){return new JSONObject[]{caldron(),eddy(),elder(),scout(),terran(),virvos()};}
 public static synchronized JSONObject install(){int d=0,i=0,b=0;JSONArray f=new JSONArray();try{for(JSONObject r:records()){String id=r.optString("id");try{JSONObject x=AuthorizedBestiaryScopeEngine.declare(new JSONObject().put("id",id).put("source_book",BOOK).put("source_locator",r.optJSONObject("mechanical_basis").optString("source_locator")));if(x.optBoolean("accepted"))d++;CompiledStatblockEngine.registerAuthorized(r);i++;}catch(Exception e){b++;f.put(id);}}return new JSONObject().put("source",SOURCE_CODE).put("scope_declared",d).put("statblocks_installed",i).put("blocked",b).put("failures",f).put("auto_rolls",false).put("runtime_tier","tactical_runtime");}catch(Exception e){return new JSONObject();}}
 public static JSONObject coverage(){JSONObject o=new JSONObject();try{int r=0;JSONArray m=new JSONArray();for(String id:IDS){if(CompiledStatblockEngine.has(id))r++;else m.put(id);}return o.put("source",SOURCE_CODE).put("expected",IDS.length).put("tactical_runtime",r).put("pending",IDS.length-r).put("complete_tactical",r==IDS.length).put("full_nf_claim",false).put("remaining_scope","anomalies|hazards|items|lore").put("missing",m);}catch(Exception e){return o;}}
}
